// The core's client (003 §4): the contract's messages, generated by Wire from Core/proto; the
// Rust core as libwebtiger_core.so, built from Core/ for both ABIs with the NDK's clang; and
// CoreClient over it, with NativeCore (the real core) and ScriptedCore (for tests). The JVM
// tests drive the real core: the same library built for this machine, JNI glue included.
import com.android.build.api.variant.LibraryAndroidComponentsExtension
import javax.inject.Inject
import org.gradle.process.ExecOperations

plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.wire)
}

/** The ABIs the app ships, each with the Rust target it is built for. */
val rustTargets = mapOf("arm64-v8a" to "aarch64-linux-android", "x86_64" to "x86_64-linux-android")

val minimumApi = libs.versions.min.sdk.get().toInt()

android {
    namespace = "com.tigercodes.webtiger.core"
    compileSdk = libs.versions.compile.sdk.get().toInt()
    buildToolsVersion = libs.versions.build.tools.get()
    ndkVersion = libs.versions.ndk.get()
    defaultConfig {
        minSdk = minimumApi
        // What the core calls over JNI is found by name: kept when the app is shrunk.
        consumerProguardFiles("consumer-rules.pro")
    }
    testOptions {
        unitTests.all { test ->
            test.testLogging {
                events("failed")
                exceptionFormat = org.gradle.api.tasks.testing.logging.TestExceptionFormat.FULL
            }
            // The tests load the core's library; newer JDKs warn, and will refuse, unless told.
            test.jvmArgs("--enable-native-access=ALL-UNNAMED")
        }
    }
}

wire {
    sourcePath {
        srcDir(rootDir.resolve("../Core/proto"))
    }
    kotlin {}
}

dependencies {
    api(libs.wire.runtime)
    api(libs.kotlinx.coroutines.core)
    testImplementation(libs.junit)
    testImplementation(libs.kotlinx.coroutines.test)
}

/** Builds libwebtiger_core.so for each ABI with the NDK's clang, and lays them out as jniLibs. */
abstract class CargoAndroidTask : DefaultTask() {
    @get:Inject abstract val exec: ExecOperations

    @get:Internal abstract val coreDir: DirectoryProperty

    @get:Internal abstract val ndkDir: DirectoryProperty

    @get:Input abstract val targets: MapProperty<String, String>

    @get:Input abstract val api: Property<Int>

    @get:OutputDirectory abstract val outputDir: DirectoryProperty

    init {
        // Cargo knows what is stale. Declaring Core/ an input would hash its build outputs.
        outputs.upToDateWhen { false }
    }

    @TaskAction
    fun build() {
        val os = System.getProperty("os.name").lowercase()
        val windows = os.contains("windows")
        val prebuilt =
            when {
                windows -> "windows-x86_64"
                os.contains("mac") -> "darwin-x86_64"
                else -> "linux-x86_64"
            }
        val bin = ndkDir.get().asFile.resolve("toolchains/llvm/prebuilt/$prebuilt/bin")
        if (!bin.isDirectory) throw GradleException("The NDK's toolchain is not at $bin")
        val core = coreDir.get().asFile
        for ((abi, target) in targets.get()) {
            val clang = bin.resolve("$target${api.get()}-clang${if (windows) ".cmd" else ""}").path
            val cargoName = target.uppercase().replace('-', '_')
            val ccName = target.replace('-', '_')
            exec.exec {
                workingDir = core
                commandLine(
                    "cargo", "build", "-p", "wt-ffi", "--features", "jni", "--release", "--locked",
                    "--target", target, "--target-dir", "target/android",
                )
                environment("CARGO_TARGET_${cargoName}_LINKER", clang)
                // The C the core's crates compile (SQLite) is built by the same clang.
                environment("CC_$ccName", clang)
                environment("AR_$ccName", bin.resolve("llvm-ar${if (windows) ".exe" else ""}").path)
                // 16 KB pages (Android 15 and later).
                environment("CARGO_TARGET_${cargoName}_RUSTFLAGS", "-C link-arg=-Wl,-z,max-page-size=16384")
            }
            val library = core.resolve("target/android/$target/release/libwebtiger_core.so")
            val destination = outputDir.get().asFile.resolve(abi)
            destination.mkdirs()
            library.copyTo(destination.resolve(library.name), overwrite = true)
        }
    }
}

/** Builds the core for this machine, JNI glue included: the library the JVM tests load. */
abstract class CargoHostTask : DefaultTask() {
    @get:Inject abstract val exec: ExecOperations

    @get:Internal abstract val coreDir: DirectoryProperty

    init {
        outputs.upToDateWhen { false }
    }

    @TaskAction
    fun build() {
        exec.exec {
            workingDir = coreDir.get().asFile
            commandLine("cargo", "build", "-p", "wt-ffi", "--features", "jni", "--locked", "--target-dir", "target/jvm")
        }
    }
}

val coreDirectory = layout.projectDirectory.dir("../../Core")

val androidComponents = extensions.getByType(LibraryAndroidComponentsExtension::class.java)
androidComponents.onVariants { variant ->
    val cargo =
        tasks.register<CargoAndroidTask>("cargoBuild${variant.name.replaceFirstChar { it.uppercase() }}") {
            coreDir.set(coreDirectory)
            ndkDir.set(androidComponents.sdkComponents.ndkDirectory)
            targets.set(rustTargets)
            api.set(minimumApi)
            outputDir.set(layout.buildDirectory.dir("rustJniLibs/${variant.name}"))
        }
    variant.sources.jniLibs?.addGeneratedSourceDirectory(cargo, CargoAndroidTask::outputDir)
}

val cargoHost =
    tasks.register<CargoHostTask>("cargoBuildHost") {
        coreDir.set(coreDirectory)
    }

tasks.withType<Test>().configureEach {
    dependsOn(cargoHost)
    val libraries = coreDirectory.dir("target/jvm/debug")
    systemProperty("java.library.path", libraries.asFile.absolutePath)
    // The contract's constants in Kotlin are checked against the C header.
    systemProperty("webtiger.core.header", coreDirectory.file("crates/wt-ffi/include/webtiger_core.h").asFile.absolutePath)
    // The library path hides the core's library from Gradle: named as an input, a change to the
    // core runs these tests again.
    inputs.file(libraries.file(System.mapLibraryName("webtiger_core")))
        .withPropertyName("coreLibrary")
        .withPathSensitivity(PathSensitivity.NONE)
}
